import { StorageSource } from "./storage";
import { Role, User } from "../users";
import { RebaseData } from "./data";

/**
 * Capabilities advertised by an auth provider.
 * UI components use this to show/hide features dynamically
 * (e.g. password reset, registration, session management).
 * @group Hooks and utilities
 */
export interface AuthCapabilities {
    emailPasswordLogin?: boolean;
    googleLogin?: boolean;
    registration?: boolean;
    passwordReset?: boolean;
    sessionManagement?: boolean;
    profileUpdate?: boolean;
    emailVerification?: boolean;
}

/**
 * Controller for retrieving the logged user or performing auth related operations.
 * Note that if you are implementing your AuthController, you probably will want
 * to do it as the result of a hook.
 * @group Hooks and utilities
 */
export type AuthController<USER extends User = any, ExtraData = unknown> = {

    /**
     * The user currently logged in
     * The values can be: the user object, null if they skipped login
     */
    user: USER | null;

    /**
     * Initial loading flag. It is used not to display the login screen
     * when the app first loads, and it has not been checked whether the user
     * is logged in or not.
     */
    initialLoading?: boolean;

    /**
     * Loading flag. It is used to display a loading screen when the user is
     * logging in or out.
     */
    authLoading: boolean;

    /**
     * Sign out
     */
    signOut: () => Promise<void>;

    /**
     * Error initializing the authentication
     */
    authError?: unknown;

    /**
     * Error dispatched by the auth provider
     */
    authProviderError?: unknown;

    /**
     * You can use this method to retrieve the auth token for the current user.
     */
    getAuthToken: () => Promise<string>;

    /**
     * Has the user skipped the login process
     */
    loginSkipped: boolean;

    extra: ExtraData;

    setExtra: (extra: ExtraData) => void;


    setUser?: (user: USER | null) => void;

    setUserRoles?: (roles: Role[]) => void;

    /**
     * Capabilities advertised by the auth provider.
     * UI components use this to feature-detect what the backend supports.
     */
    capabilities?: AuthCapabilities;

};

/**
 * Extended auth controller with common optional auth methods.
 * Backend implementations (Rebase backend, Firebase, Supabase, etc.)
 * extend this with their own backend-specific extras.
 * @group Hooks and utilities
 */
export interface AuthControllerExtended<USER extends User = any, ExtraData = unknown> extends AuthController<USER, ExtraData> {
    /** Login with email and password */
    emailPasswordLogin?: (email: string, password: string) => Promise<void>;
    /** Login with a Google ID token or trigger Google popup */
    googleLogin?: (idToken: string) => Promise<void>;
    /** Register a new user */
    register?: (email: string, password: string, displayName?: string) => Promise<void>;
    /** Skip login (for anonymous access if enabled) */
    skipLogin?: () => void;
    /** Request password reset email */
    forgotPassword?: (email: string) => Promise<void>;
    /** Reset password using a token */
    resetPassword?: (token: string, password: string) => Promise<void>;
    /** Change password for the authenticated user */
    changePassword?: (oldPassword: string, newPassword: string) => Promise<void>;
    /** Update user profile */
    updateProfile?: (displayName?: string, photoURL?: string) => Promise<USER>;
}

/**
 * Implement this function to allow access to specific users.
 * @group Hooks and utilities
 */
export type Authenticator<USER extends User = User> = (props: {

    /**
     * Logged-in user or null
     */
    user: USER | null;

    /**
     * AuthController
     */
    authController: AuthController<USER>;

    /**
     * Unified data access API
     */
    data: RebaseData;

    /**
     * Used storage implementation
     */
    storageSource: StorageSource;

}) => boolean | Promise<boolean>;

import { User } from "../users";
import { RebaseData } from "./data";

/**
 * Event type for authentication state changes
 */
export type AuthChangeEvent = 'SIGNED_IN' | 'SIGNED_OUT' | 'TOKEN_REFRESHED' | 'USER_UPDATED';

/**
 * Standard session interface representing an authenticated state
 */
export interface RebaseSession {
    accessToken: string;
    refreshToken: string;
    expiresAt: number;
    user: User;
}

import { StorageSource } from "./storage";

/**
 * Unified Authentication Client Interface
 * Pure functional SDK interface, decoupled from UI and React hooks
 */
export interface AuthClient {
    /**
     * Get the current user from the server or cache
     */
    getUser(): Promise<User | null>;

    /**
     * Get the currently active session
     */
    getSession(): RebaseSession | null;

    /**
     * Sign out the current user and clear local session
     */
    signOut(): Promise<void>;

    /**
     * Subscribe to authentication state changes
     */
    onAuthStateChange(callback: (event: AuthChangeEvent, session: RebaseSession | null) => void): () => void;

    /**
     * Manually refresh the session token
     */
    refreshSession(): Promise<RebaseSession>;

    // Extensible for backend implementations
    [key: string]: any;
}

/**
 * Overarching abstraction that unites Data, Auth, and Storage.
 * Adapters for Supabase or Firebase simply need to implement this interface.
 */
export interface RebaseClient<DB = any> {
    /** Unified Data access layer */
    data: RebaseData;

    /** Unified Authentication layer */
    auth: AuthClient;

    /** Unified Storage layer */
    storage?: StorageSource;

    /** Optional admin panel specific tasks */
    admin?: any;

    // Generic extensibility
    [key: string]: any;
}

import { EntityCollection, EntityReference } from "../types";

/**
 * Controller that provides access to the registered entity collections.
 * @group Models
 */
export type CollectionRegistryController<EC extends EntityCollection = EntityCollection<any>> = {

    /**
     * List of the mapped collections in the CMS.
     * Each entry relates to a collection in the root database.
     * Each of the navigation entries in this field
     * generates an entry in the main menu.
     */
    collections?: EntityCollection[];

    /**
     * Is the registry ready to be used
     */
    initialised: boolean;

    /**
     * Get the collection configuration for a given path.
     * The collection is resolved from the given path or alias.
     */
    getCollection: (slugOrPath: string, includeUserOverride?: boolean) => EC | undefined;

    /**
     * Get the raw, un-normalized collection configuration.
     * This bypasses the `CollectionRegistry` normalization (such as injecting `relation` instances).
     * This is strictly for the Visual Editor to manipulate AST code without persisting runtime state.
     */
    getRawCollection: (slugOrPath: string) => EC | undefined;

    /**
     * Retrieve all the related parent references for a given path
     * @param path
     */
    getParentReferencesFromPath: (path: string) => EntityReference[];

    /**
     * Retrieve all the related parent collection ids for a given path
     * @param path
     */
    getParentCollectionIds: (path: string) => string[];

    /**
     * Resolve paths from a list of ids
     * @param ids
     */
    convertIdsToPaths: (ids: string[]) => string[];

};

import { Entity, EntityValues } from "../types/entities";

/**
 * Parameters for querying a collection.
 * Uses PostgREST-style filter syntax for consistency between
 * the SDK (HTTP) and framework (in-process) contexts.
 *
 * @group Data
 */
export interface FindParams {
    /** Maximum number of items to return (default: 20) */
    limit?: number;
    /** Number of items to skip */
    offset?: number;
    /** Page number (1-indexed), alternative to offset */
    page?: number;
    /**
     * PostgREST-style filter object.
     * Keys are field names, values use "operator.value" format.
     * Operators: eq, neq, gt, gte, lt, lte, in, nin, cs (array-contains), csa (array-contains-any)
     *
     * @example
     * { status: "eq.published" }
     * { age: "gte.18" }
     * { role: "in.(admin,editor)" }
     */
    where?: Record<string, string>;
    /**
     * Sort order. Format: "field:direction".
     * @example "created_at:desc", "name:asc"
     */
    orderBy?: string;
    /** Relations to include in the response */
    include?: string[];
    /** Full-text search string */
    searchString?: string;
}

/**
 * Paginated response from a collection query.
 * @group Data
 */
export interface FindResponse<M extends Record<string, any> = any> {
    /** Array of entities matching the query */
    data: Entity<M>[];
    /** Pagination metadata */
    meta: {
        total: number;
        limit: number;
        offset: number;
        hasMore: boolean;
    };
}

/**
 * A single collection's CRUD accessor.
 *
 * This is the unified API surface used in both:
 * - The generated SDK (`client.data.products.create(...)`)
 * - Framework callbacks (`context.data.products.create(...)`)
 *
 * @group Data
 */
export interface CollectionAccessor<M extends Record<string, any> = any> {
    /**
     * Find multiple records with optional filtering, pagination, and sorting.
     */
    find(params?: FindParams): Promise<FindResponse<M>>;

    /**
     * Find a single record by its ID.
     */
    findById(id: string | number): Promise<Entity<M> | undefined>;

    /**
     * Create a new record.
     * @param data The entity data to create.
     * @param id Optional specific ID to use for the new record.
     * @returns The created entity
     */
    create(data: Partial<EntityValues<M>>, id?: string | number): Promise<Entity<M>>;

    /**
     * Update an existing record by ID.
     * @returns The updated entity
     */
    update(id: string | number, data: Partial<EntityValues<M>>): Promise<Entity<M>>;

    /**
     * Delete a record by ID.
     */
    delete(id: string | number): Promise<void>;

    /**
     * Subscribe to a collection for real-time updates.
     * Optional method, may not be supported by all implementations (like stateless HTTP clients).
     */
    listen?(params: FindParams | undefined, onUpdate: (response: FindResponse<M>) => void, onError?: (error: Error) => void): () => void;

    /**
     * Subscribe to a single record for real-time updates.
     * Optional method.
     */
    listenById?(id: string | number, onUpdate: (entity: Entity<M> | undefined) => void, onError?: (error: Error) => void): () => void;

    /**
     * Count the number of records matching the given filter.
     */
    count?(params?: FindParams): Promise<number>;
}

/**
 * The unified data access object.
 *
 * Access collections as dynamic properties: `data.products.find(...)`.
 * In the SDK this is backed by HTTP transport (typed, generated per-project).
 * In the framework this is backed by a Proxy + in-process database driver (dynamic).
 *
 * @example
 * // SDK
 * const client = createRebaseClient({ baseUrl: "..." });
 * await client.data.products.create({ name: "Camera", price: 299 });
 *
 * // Framework callback
 * callbacks: {
 *   afterSave({ context }) {
 *     await context.data.logs.create({ action: "saved", timestamp: new Date() });
 *   }
 * }
 *
 * @group Data
 */
export interface RebaseData {
    /**
     * Get a collection accessor by slug.
     * Alternative to dynamic property access for cases where
     * the collection name is a variable.
     *
     * @example
     * const accessor = data.collection("products");
     * await accessor.find({ limit: 10 });
     */
    collection(slug: string): CollectionAccessor;

    /**
     * Dynamic collection accessor.
     * Access any collection by its slug as a property.
     *
     * @example
     * data.products.find({ where: { status: "eq.published" } })
     */
    [collectionSlug: string]: CollectionAccessor | ((slug: string) => CollectionAccessor);
}

import { CollectionRegistryController } from "./collection_registry";
import { Entity, EntityCollection, EntityStatus, EntityValues, FilterValues } from "../types";
import { RebaseContext } from "../rebase_context";
import { TableMetadata } from "../types/websockets";

/**
 * @internal
 */
export interface FetchEntityProps<M extends Record<string, any> = any> {
    path: string;
    entityId: string | number;
    databaseId?: string;
    collection?: EntityCollection<M, any>
}

/**
 * @internal
 */
export type ListenEntityProps<M extends Record<string, any> = any> =
    FetchEntityProps<M>
    & {
        onUpdate: (entity: Entity<M> | null) => void,
        onError?: (error: Error) => void,
    }

/**
 * @internal
 */
export interface FetchCollectionProps<M extends Record<string, any> = any> {
    path: string;
    collection?: EntityCollection<M>;
    filter?: FilterValues<Extract<keyof M, string>>,
    limit?: number;
    startAfter?: unknown;
    orderBy?: string;
    searchString?: string;
    order?: "desc" | "asc";
}

/**
 * @internal
 */
export type ListenCollectionProps<M extends Record<string, any> = any> =
    FetchCollectionProps<M> &
    {
        onUpdate: (entities: Entity<M>[]) => void;
        onError?: (error: Error) => void;
    };

/**
 * @internal
 */
export interface SaveEntityProps<M extends Record<string, any> = any> {
    path: string;
    values: Partial<EntityValues<M>>;
    entityId?: string | number; // can be empty for new entities
    previousValues?: Partial<EntityValues<M>>;
    collection?: EntityCollection<M>;
    status: EntityStatus;
}

/**
 * @internal
 */
export interface DeleteEntityProps<M extends Record<string, any> = any> {
    entity: Entity<M>;
    collection?: EntityCollection<M>;
}

export type FilterCombinationValidProps = {
    path: string;
    databaseId?: string;
    collection: EntityCollection<any>;
    filterValues: FilterValues<any>;
    sortBy?: [string, "asc" | "desc"];
};

/**
 * Internal driver interface for communicating with the data layer.
 * This is NOT the public API — use `RebaseData` / `context.data` instead.
 * @internal
 */
export interface DataDriver {

    /**
     * Key that identifies this driver
     */
    key?: string;

    /**
     * If the driver has been initialised
     */
    initialised?: boolean;

    /**
     * Fetch data from a collection
     * @param props
     * @return Promise of entities
     */
    fetchCollection<M extends Record<string, any> = any>(props: FetchCollectionProps<M>): Promise<Entity<M>[]>;

    /**
     * Listen to a collection in a given path. If you don't implement this method
     * `fetchCollection` will be used instead, with no real time updates.
     * @param props
     * @return Function to cancel subscription
     */
    listenCollection?<M extends Record<string, any> = any>(props: ListenCollectionProps<M>): () => void;

    /**
     * Retrieve an entity given a path and a collection
     * @param props
     */
    fetchEntity<M extends Record<string, any> = any>(props: FetchEntityProps<M>): Promise<Entity<M> | undefined>;

    /**
     * Get realtime updates on one entity.
     * @param props
     * @return Function to cancel subscription
     */
    listenEntity?<M extends Record<string, any> = any>(props: ListenEntityProps<M>): () => void;

    /**
     * Save entity to the specified path
     * @param props
     */
    saveEntity<M extends Record<string, any> = any>(props: SaveEntityProps<M>): Promise<Entity<M>>;

    /**
     * Delete an entity
     * @param props
     * @return was the whole deletion flow successful
     */
    deleteEntity<M extends Record<string, any> = any>(props: DeleteEntityProps<M>): Promise<void>;

    /**
     * Check if the given property is unique in the given collection
     * @param path Collection path
     * @param name of the property
     * @param value
     * @param entityId
     * @param collection
     * @return `true` if there are no other fields besides the given entity
     */
    checkUniqueField(
        path: string,
        name: string,
        value: unknown,
        entityId?: string | number,
        collection?: EntityCollection
    ): Promise<boolean>;

    /**
     * Count the number of entities in a collection
     */
    countEntities?<M extends Record<string, any> = any>(props: FetchCollectionProps<M>): Promise<number>;

    /**
     * Check if the given filter combination is valid
     * @param props
     */
    isFilterCombinationValid?(props: Omit<FilterCombinationValidProps, "collection"> & {
        databaseId?: string
    }): boolean;

    /**
     * Get the object to generate the current time in the driver
     */
    currentTime?: () => unknown;

    delegateToCMSModel?: (data: unknown) => unknown;

    cmsToDelegateModel?: (data: unknown) => unknown;

    initTextSearch?: (props: {
        context: RebaseContext,
        path: string,
        databaseId?: string,
        collection: EntityCollection,
        parentCollectionIds?: string[]
    }) => Promise<boolean>;

    /**
     * Flag to indicate if the driver has requested the initialization of the text search index
     */
    needsInitTextSearch?: boolean;

    // ── Admin capabilities ─────────────────────────────────────────────
    //
    // Admin operations are now modelled as capability-specific interfaces
    // (SQLAdmin, DocumentAdmin, SchemaAdmin) in `@rebasepro/types/backend`.
    //
    // Drivers that support admin features should expose them here.
    // Consumers should use the `isSQLAdmin()`, `isSchemaAdmin()` etc.
    // type guards to safely narrow the type before calling methods.

    /**
     * Return the admin capabilities of this driver.
     * @see SQLAdmin
     * @see DocumentAdmin
     * @see SchemaAdmin
     */
    admin?: import("../types/backend").DatabaseAdmin;

    // ── Direct admin methods ────────────────────────────────────────────
    // These convenience methods are kept on the driver interface for
    // simple use cases. For capability-based access, use `driver.admin`
    // with `isSQLAdmin()` / `isSchemaAdmin()` type guards.

    executeSql?(sql: string, options?: { database?: string; role?: string }): Promise<Record<string, unknown>[]>;

    fetchAvailableDatabases?(): Promise<string[]>;

    fetchAvailableRoles?(): Promise<string[]>;

    fetchCurrentDatabase?(): Promise<string | undefined>;

    fetchUnmappedTables?(mappedPaths?: string[]): Promise<string[]>;

    fetchTableMetadata?(tableName: string): Promise<TableMetadata>;

}

/**
 * @module database_admin
 *
 * Re-exports the capability-specific admin interfaces from `@rebasepro/types/backend`.
 * This file is kept for backwards compatibility — new code should import from
 * `@rebasepro/types` directly.
 *
 * @group Admin
 */
export type {
    SQLAdmin,
    DocumentAdmin,
    SchemaAdmin,
    DatabaseAdmin,
    HealthCheckResult,
} from "../types/backend";

export {
    isSQLAdmin,
    isDocumentAdmin,
    isSchemaAdmin,
} from "../types/backend";

import React from "react";

/**
 * Controller to open the side dialog
 * @group Hooks and utilities
 */
export interface DialogsController {

    /**
     * Close the last dialog
     */
    close: () => void;

    /**
     * Open a dialog
     * @param props
     */
    open: <T extends object = object>(props: DialogControllerEntryProps<T>) => { closeDialog: () => void };
}

/**
 * Props used to open a side dialog
 * @group Hooks and utilities
 */
export interface DialogControllerEntryProps<T extends object = object> {

    key: string;
    /**
     * The component type that will be rendered
     */
    Component: React.ComponentType<{ open: boolean, closeDialog: () => void } & T>;
    /**
     * Props to pass to the dialog component
     */
    props?: T;

}

export interface EffectiveRoleController {
    effectiveRole: string | null;
    setEffectiveRole: (role: string | null) => void;
}

import { EntityCollection } from "../types";

/**
 * @group Models
 */
export type PartialEntityCollection<M extends Record<string, any> = any> = Partial<EntityCollection<M>>;

/**
 * This interface is in charge of defining the controller that persists
 * modifications to a collection or collection, and retrieves them back from
 * a data source, such as local storage or Firestore.
 */
export interface UserConfigurationPersistence {
    onCollectionModified: <M extends Record<string, any> = any>(path: string, partialCollection: PartialEntityCollection<M>) => void;
    getCollectionConfig: <M extends Record<string, any> = any>(path: string) => PartialEntityCollection<M>;
    recentlyVisitedPaths: string[];
    setRecentlyVisitedPaths: (paths: string[]) => void;
    favouritePaths: string[];
    setFavouritePaths: (paths: string[]) => void;
    collapsedGroups: string[];
    setCollapsedGroups: (paths: string[]) => void;
}

import React from "react";
import { EntityReference } from "../types/entities";import { EntityCollection } from "../types/collections";
import { RebasePlugin } from "../types/plugins";

/**
 * Controller that handles URL path building and resolution.
 * @group Models
 */
export type UrlController = {
    /**
     * Default path under the navigation routes of the CMS will be created.
     * Defaults to '/'. You may want to change this `basepath` to 'admin' for example.
     */
    basePath: string;

    /**
     * Default path under the collection routes of the CMS will be created.
     * It defaults to '/c'
     */
    baseCollectionPath: string;

    /**
     * Convert a URL path to a collection or entity path
     * `/c/products` => `products`
     * `/my_cms/c/products/B34SAP8Z` => `products/B34SAP8Z`
     * `/my_cms/my_view` => `my_view`
     * @param cmsPath
     */
    urlPathToDataPath: (cmsPath: string) => string;

    /**
     * Base url path for the home screen
     */
    homeUrl: string;

    /**
     * Check if a url path belongs to a collection
     * @param path
     */
    isUrlCollectionPath: (urlPath: string) => boolean;

    /**
     * Build a URL collection path from a data path
     * `products` => `/c/products`
     * `products/B34SAP8Z` => `/c/products/B34SAP8Z`
     * @param path
     */
    buildUrlCollectionPath: (path: string) => string;

    /**
     * Build a URL path for the CMS (e.g. for custom views)
     * @param path
     */
    buildAppUrlPath: (path: string) => string;

    /**
     * Turn a path with collection ids into a resolved path.
     * The ids (typically used in urls) will be replaced with relative paths (typically used in database paths)
     * @param path
     */
    resolveDatabasePathsFrom: (path: string) => string;

    /**
     * A function to navigate to a specified route or URL.
     *
     * @param {string} to - The target route or URL to navigate to.
     * @param {NavigateOptions} [options] - Optional configuration settings for navigation, such as replace behavior or state data.
     */
    navigate: (to: string, options?: NavigateOptions) => void;
};

/**
 * Controller that manages the state of the navigation menu,
 * including resolved views and top-level grouping.
 * @group Models
 */
export type NavigationStateController = {
    /**
     * Custom additional views created by the developer, added to the main
     * navigation
     */
    views?: AppView[];

    /**
     * Custom additional views created by the developer, added to the admin
     * navigation
     */
    adminViews?: AppView[];

    /**
     * Configuration for the views that should be displayed at the top
     * level of the navigation (e.g. in the home page or the navigation
     * drawer)
     */
    topLevelNavigation?: NavigationResult;

    /**
     * Is the navigation loading (the configuration persistence has not
     * loaded yet, or a specified navigation builder has not completed)
     */
    loading: boolean;

    /**
     * Was there an error while loading the navigation data
     */
    navigationLoadingError?: unknown;

    /**
     * Call this method to recalculate the navigation
     */
    refreshNavigation: () => void;

    /**
     * Plugin system allowing to extend the CMS functionality.
     */
    plugins?: RebasePlugin[];
};

export interface NavigateOptions {
    replace?: boolean;
    state?: unknown;
    preventScrollReset?: boolean;
    relative?: "route" | "path";
    flushSync?: boolean;
    viewTransition?: boolean;
}

// currently not used, in favor of a single blocker in `RebaseRoute`
export type NavigationBlocker = {
    updateBlockListener: (path: string, block: boolean, basePath?: string) => () => void;
    isBlocked: (path: string) => boolean;
    proceed?: () => void;
    reset?: () => void;
};

/**
 * Custom additional views created by the developer, added to the main
 * navigation.
 * @group Models
 */
export interface AppView {

    /**
     * CMS Path you can reach this view from.
     */
    slug: string;

    /**
     * Name of this view
     */
    name: string;

    /**
     * Optional description of this view. You can use Markdown
     */
    description?: string;

    /**
     * Icon key to use in this view.
     * You can use any of the icons in the Material specs:
     * https://fonts.google.com/icons
     * e.g. 'account_tree' or 'person'
     * Find all the icons in https://rebase.pro/docs/icons
     */
    icon?: string | React.ReactNode;

    /**
     * Should this view be hidden from the main navigation panel.
     * It will still be accessible if you reach the specified path
     */
    hideFromNavigation?: boolean;

    /**
     * Component to be rendered. This can be any React component, and can use
     * any of the provided hooks
     */
    view: React.ReactNode;

    /**
     * Optional field used to group top level navigation entries under a
     * navigation view.
     * This prop is ignored for admin views.
     */
    group?: string;

    /**
     * If true, a wildcard route (slug/*) is automatically registered
     * alongside the base route, enabling nested navigation within this view.
     */
    nestedRoutes?: boolean;

}

/**
 * A composable section that can be rendered on the home page.
 * Use this to add custom content alongside the auto-generated
 * navigation groups.
 * @group Models
 */
export interface HomePageSection {
    /**
     * Unique key for this section.
     */
    key: string;

    /**
     * Title displayed as the section header.
     */
    title: string;

    /**
     * Arbitrary React content rendered inside the section.
     */
    children: React.ReactNode;
}

/**
 * Used to group navigation entries in the main navigation.
 */
export interface NavigationGroupMapping {
    /**
     * Name of the group, used to display the group header in the UI
     */
    name: string;
    /**
     * List of collection ids or view paths that belong to this group.
     */
    entries: string[];
}

export interface NavigationEntry {
    id: string;
    url: string;
    name: string;
    slug: string;
    type: "collection" | "view" | "admin";
    collection?: EntityCollection;
    view?: AppView;
    description?: string;
    group: string;
}

export type NavigationResult = {

    allowDragAndDrop: boolean;

    navigationEntries: NavigationEntry[],

    groups: string[],

    onNavigationEntriesUpdate: (entries: NavigationGroupMapping[]) => void;
};

import { ReactNode } from "react";
import { EntityCollection, EntityCollectionsBuilder, EntityCustomView, EntityAction } from "../types";
import { AppView } from "./navigation";

/**
 * Options to enable the built-in collection editor.
 * When provided to `<RebaseCMS>`, the editor is auto-wired as a native feature.
 */
export interface CollectionEditorOptions {
    /**
     * Function that returns an auth token for schema-editor API calls.
     * Falls back to `authController.getAuthToken` when omitted.
     */
    getAuthToken?: () => Promise<string | null>;
    /** Mark the editor as read-only (disable mutations). */
    readOnly?: boolean;
    /** Suggested base paths shown when creating new collections. */
    pathSuggestions?: string[];
}

export interface RebaseCMSConfig<EC extends EntityCollection = any> {
    collections?: EC[] | EntityCollectionsBuilder<EC>;
    homePage?: ReactNode;
    entityViews?: EntityCustomView<any>[];
    entityActions?: EntityAction[];
    plugins?: any[];

    /**
     * Enable the built-in visual collection/schema editor.
     * Pass `true` for zero-config, or an options object for fine-grained control.
     * When enabled, the editor slots, provider, and Studio schema view
     * are all auto-wired — no plugin or manual view injection needed.
     */
    collectionEditor?: boolean | CollectionEditorOptions;
}

export interface RebaseStudioConfig {
    tools?: ("sql" | "js" | "rls" | "schema" | "storage")[];
    homePage?: ReactNode;
    devViews?: AppView[];
}

export interface RebaseAuthConfig {
    loginView?: ReactNode;
}

export interface RebaseRegistryController {
    // Current state
    cmsConfig: RebaseCMSConfig | null;
    studioConfig: RebaseStudioConfig | null;
    authConfig: RebaseAuthConfig | null;

    // Registration functions
    registerCMS: (config: RebaseCMSConfig) => void;
    unregisterCMS: () => void;

    registerStudio: (config: RebaseStudioConfig) => void;
    unregisterStudio: () => void;

    registerAuth: (config: RebaseAuthConfig) => void;
    unregisterAuth: () => void;
}

import React from "react";

/**
 * Controller to open the side dialog
 * @group Hooks and utilities
 */
export interface SideDialogsController {

    /**
     * Close the last panel
     */
    close: () => void;

    /**
     * List of side panels currently open
     */
    sidePanels: SideDialogPanelProps[];

    /**
     * Override the current side panels
     * @param panels
     */
    setSidePanels: (panels: SideDialogPanelProps[]) => void;

    /**
     * Open one or multiple side panels
     * @param props
     */
    open: (panelProps: SideDialogPanelProps | SideDialogPanelProps[]) => void;

    /**
     * Replace the last open panel with the given one
     * @param props
     */
    replace: (panelProps: SideDialogPanelProps | SideDialogPanelProps[]) => void;
}

/**
 * Props used to open a side dialog
 * @group Hooks and utilities
 */
export interface SideDialogPanelProps {

    /**
     * A key that identifies this panel
     */
    key: string;

    /**
     * The component type that will be rendered
     */
    component: React.ReactNode;

    /**
     * Optional width of the panel
     */
    width?: string;

    /**
     * When open, change the URL to this path.
     * Note that if you want to restore state from a URL you need to add the
     * logic yourself by listening to URL updates, and probably call `open`.
     */
    urlPath?: string;

    /**
     * If the navigation stack is empty (you landed in the `urlPath` url), what
     * url path to change to when the panel gets closed.
     */
    parentUrlPath?: string;

    /**
     * Callback when the panel is closed
     */
    onClose?: () => void;

    /**
     * Use this prop to store additional data in the panel
     */
    additional?: unknown;

}

import { Entity, EntityCollection } from "../types";

/**
 * Props used to open a side dialog
 * @group Hooks and utilities
 */
export interface EntitySidePanelProps<M extends Record<string, any> = any> {

    /**
     * Absolute path of the entity
     */
    path: string;

    /**
     * ID of the entity, if not set, it means we are creating a new entity
     */
    entityId?: string | number;

    /**
     * Set this flag to true if you want to make a copy of an existing entity
     */
    copy?: boolean;

    /**
     * Open the entity with a selected sub-collection view. If the panel for this
     * entity was already open, it is replaced.
     */
    selectedTab?: string;

    /**
     * Use this prop to override the width of the form view.
     * e.g. "600px"
     */
    width?: number | string;

    /**
     * Collection representing the entities of this view.
     * If you leave it blank it will be induced by your navigation
     */
    collection?: EntityCollection<M>;

    /**
     * Should update the URL when opening the dialog.
     * Consider that if the collection that you provide is not defined in the base
     * config of your `Rebase` component, you will not be able to recreate
     * the state if copying the URL to a different window.
     */
    updateUrl?: boolean;

    /**
     * Callback when the entity is updated
     * @param params
     */
    onUpdate?: (params: { entity: Entity<any> }) => void;

    /**
     * Callback when the dialog is closed
     */
    onClose?: () => void;

    /**
     * Should this panel close when saving
     */
    closeOnSave?: boolean;

    /**
     * Override some form properties
     */
    formProps?: any;

    /**
     * Allow the user to open the entity fullscreen
     */
    allowFullScreen?: boolean;
}

/**
 * Controller to open the side dialog displaying entity forms
 * @group Hooks and utilities
 */
export interface SideEntityController {
    /**
     * Close the last panel
     */
    close: () => void;

    /**
     * Open a new entity sideDialog. By default, the collection and configuration
     * of the view is fetched from the collections you have specified in the
     * navigation.
     * At least you need to pass the path of the entity you would like
     * to edit. You can set an entityId if you would like to edit and existing one
     * (or a new one with that id).
     * @param props
     */
    open: <M extends Record<string, any> = any>(props: EntitySidePanelProps<M>) => void;

    /**
     * Replace the last open entity panel with the given one.
     * @param props
     */
    replace: <M extends Record<string, any> = any>(props: EntitySidePanelProps<M>) => void;
}

/**
 * Possible snackbar types
 * @group Hooks and utilities
 */
export type SnackbarMessageType = "success" | "info" | "warning" | "error";

/**
 * Controller to display snackbars
 * @group Hooks and utilities
 */
export interface SnackbarController {

    /**
     * Close the currently open snackbar
     */
    close: () => void;

    /**
     * Display a new snackbar. You need to specify the type and message.
     * You can optionally specify a title
     */
    open: (props: {
        type: SnackbarMessageType;
        message: React.ReactNode;
        autoHideDuration?: number;
    }) => void;

}

/**
 * @group Models
 */
export interface UploadFileProps {
    file: File,
    fileName?: string,
    path?: string,
    metadata?: Record<string, unknown>,
    bucket?: string
}

/**
 * @group Models
 */
export interface UploadFileResult {
    /**
     * Storage path including the file name where the file was uploaded.
     */
    path: string;
    /**
     * Bucket where the file was uploaded
     */
    bucket: string;

    /**
     * Fully qualified storage URL for the uploaded file.
     *
     * For example: `gs://my-bucket/path/to/file.png`.
     *
     * This is optional for backwards compatibility.
     */
    storageUrl?: string;
}

/**
 * @group Models
 */
export interface DownloadConfig {
    /**
     * Temporal url that can be used to download the file
     */
    url: string | null;

    metadata?: DownloadMetadata;

    fileNotFound?: boolean;
}

/**
 * The full set of object metadata, including read-only properties.
 * @public
 */
export declare interface DownloadMetadata {
    /**
     * The bucket this object is contained in.
     */
    bucket: string;
    /**
     * The full path of this object.
     */
    fullPath: string;
    /**
     * The short name of this object, which is the last component of the full path.
     * For example, if path is 'full/path/image.png', name is 'image.png'.
     */
    name: string;
    /**
     * The size of this object, in bytes.
     */
    size: number;
    /**
     * Type of the uploaded file
     * e.g. "image/jpeg"
     */
    contentType: string;

    customMetadata: Record<string, unknown>;
}

/**
 * @group Models
 */
export interface StorageSource {
    /**
     * Upload a file, specifying a name and a path
     * @param file
     * @param fileName
     * @param path
     * @param metadata
     * @param bucket
     */
    uploadFile: ({
                     file,
                     fileName,
                     path,
                     metadata,
                     bucket
                 }: UploadFileProps) => Promise<UploadFileResult>;

    /**
     * Convert a storage path or URL into a download configuration
     * @param path
     * @param bucket
     */
    getDownloadURL: (pathOrUrl: string, bucket?: string) => Promise<DownloadConfig>;

    /**
     * Get a file from a storage path.
     * It returns null if the file does not exist.
     * @param props
     * @param bucket
     */
    getFile: (path: string, bucket?: string) => Promise<File | null>;

    /**
     * Delete a file.
     * @param path
     * @param bucket
     */
    deleteFile: (path: string, bucket?: string) => Promise<void>;

    /**
     * List the contents of a path.
     * @param path
     * @param options
     */
    list: (path: string, options?: {
        bucket?: string,
        maxResults?: number,
        pageToken?: string
    }) => Promise<StorageListResult>;

}

/**
 * Result returned by list().
 * @public
 */
export declare interface StorageListResult {
    /**
     * References to prefixes (sub-folders). You can call list() on them to
     * get its contents.
     *
     * Folders are implicit based on '/' in the object paths.
     * For example, if a bucket has two objects '/a/b/1' and '/a/b/2', list('/a')
     * will return '/a/b' as a prefix.
     */
    prefixes: StorageReference[];
    /**
     * Objects in this directory.
     * You can call getMetadata() and getDownloadUrl() on them.
     */
    items: StorageReference[];
    /**
     * If set, there might be more results for this list. Use this token to resume the list.
     */
    nextPageToken?: string;
}

/**
 * Represents a reference to a Google Cloud Storage object. Developers can
 * upload, download, and delete objects, as well as get/set object metadata.
 * @public
 */
export declare interface StorageReference {
    /**
     * Returns a gs:// URL for this object in the form
     *   `gs://<bucket>/<path>/<to>/<object>`
     * @returns The gs:// URL.
     */
    toString(): string;

    /**
     * A reference to the root of this object's bucket.
     */
    root: StorageReference;
    /**
     * The name of the bucket containing this reference's object.
     */
    bucket: string;
    /**
     * The full path of this object.
     */
    fullPath: string;
    /**
     * The short name of this object, which is the last component of the full path.
     * For example, if path is 'full/path/image.png', name is 'image.png'.
     */
    name: string;

    /**
     * A reference pointing to the parent location of this reference, or null if
     * this reference is the root.
     */
    parent: StorageReference | null;
}

import {
    AnalyticsController,
    AuthController,
    StorageSource,
    UserConfigurationPersistence,
    DatabaseAdmin
} from "./controllers";

import { RebaseData } from "./controllers/data";
import { User } from "./users";
import { UserManagementDelegate } from "./types/user_management_delegate";


/**
 * Context that is provided to entity callbacks (hooks).
 * It contains only the dependencies that are available in both the frontend and the backend.
 * @group Hooks and utilities
 */
export type RebaseCallContext<USER extends User = User> = {

    /**
     * Unified data access — `context.data.products.create(...)`.
     * Access any collection as a dynamic property.
     */
    data: RebaseData;

    /**
     * Used storage implementation
     */
    storageSource: StorageSource;

    /**
     * Set by the backend when callbacks are executed on the server.
     */
    user?: USER;
}

/**
 * Context that includes the internal controllers and contexts used by the app.
 * Some controllers and context included in this context can be accessed
 * directly from their respective hooks.
 * @group Hooks and utilities
 * @see useRebaseContext
 */
export type RebaseContext<USER extends User = User, AuthControllerType extends AuthController<USER> = AuthController<USER>> = RebaseCallContext<USER> & {

    authController: AuthControllerType;

    /**
     * Controller mapping strings to collections
     */
    collectionRegistryController?: import("./controllers/collection_registry").CollectionRegistryController;

    /**
     * Controller for navigation state
     */
    navigationStateController?: import("./controllers/navigation").NavigationStateController;

    /**
     * Controller for side dialogs (side sheets)
     */
    sideDialogsController?: import("./controllers/side_dialogs_controller").SideDialogsController;

    /**
     * Controller to open the side dialog displaying entity forms
     */
    sideEntityController?: import("./controllers/side_entity_controller").SideEntityController;

    /**
     * Controller resolving URLs in the CMS
     */
    urlController?: import("./controllers/navigation").UrlController;

    /**
     * Controller to handle simple confirmation and alert dialogs
     */
    dialogsController?: import("./controllers/dialogs_controller").DialogsController;

    /**
     * Controller for CMS customization
     */
    customizationController?: import("./controllers/customization_controller").CustomizationController;

    /**
     * Controller for effective role
     */
    effectiveRoleController?: { effectiveRole: string | null, setEffectiveRole: (role: string | null) => void };

    /**
     * Use this controller to access data stored in the browser for the user
     */
    userConfigPersistence?: UserConfigurationPersistence;

    /**
     * Callback to send analytics events
     */
    analyticsController?: AnalyticsController;

    /**
     * This section is used to manage users in the CMS.
     * It is used to show user information in various places of the CMS,
     * for example, to show who created or modified an entity,
     * or to assign ownership of an entity.
     *
     * In the base CMS, this information is not used for access control.
     * You can pass your own implementation of this section, to populate
     * the dropdown of users when assigning ownership of an entity,
     * or to show more information about the user.
     *
     * If you are using the Rebase user management plugin, this
     * section will be implemented automatically.
     */
    userManagement?: UserManagementDelegate<USER>;

    /**
     * Administrative database operations (SQL, schema discovery).
     * Only available in developer/admin contexts.
     */
    databaseAdmin?: DatabaseAdmin;

    /**
     * Controller for snackbars
     */
    snackbarController?: import("./controllers/snackbar").SnackbarController;

};

import { Entity, EntityCollection, FilterValues, WhereFilterOp } from "./index";

// =============================================================================
// DATABASE CONNECTION INTERFACES
// =============================================================================

/**
 * Abstract database connection interface.
 * Represents a connection to any database system.
 */
export interface DatabaseConnection {
    /**
     * Type identifier for this database (e.g., 'postgres', 'mongodb', 'mysql')
     */
    readonly type: string;

    /**
     * Whether the connection is currently active
     */
    readonly isConnected?: boolean;

    /**
     * Close the database connection and release resources.
     */
    close?(): Promise<void>;
}

// =============================================================================
// QUERY BUILDING INTERFACES
// =============================================================================

/**
 * A single filter condition for database queries
 */
export interface QueryFilter {
    field: string;
    operator: WhereFilterOp;
    value: unknown;
}

/**
 * Options for fetching a collection of entities
 */
export interface FetchCollectionOptions<M extends Record<string, unknown> = Record<string, unknown>> {
    filter?: FilterValues<Extract<keyof M, string>>;
    orderBy?: string;
    order?: "desc" | "asc";
    limit?: number;
    startAfter?: unknown;
    searchString?: string;
    databaseId?: string;
    collection?: EntityCollection;
}

/**
 * Options for searching entities
 */
export interface SearchOptions<M extends Record<string, unknown> = Record<string, unknown>> {
    filter?: FilterValues<Extract<keyof M, string>>;
    orderBy?: string;
    order?: "desc" | "asc";
    limit?: number;
    databaseId?: string;
    collection?: EntityCollection;
}

/**
 * Options for counting entities
 */
export interface CountOptions<M extends Record<string, unknown> = Record<string, unknown>> {
    filter?: FilterValues<Extract<keyof M, string>>;
    databaseId?: string;
}

/**
 * Abstract condition builder interface.
 * Implementations translate Rebase filter conditions to database-specific queries.
 * 
 * Note: This interface can be implemented as instance methods or as a class with static methods.
 * For static implementations (like DrizzleConditionBuilder), use the ConditionBuilderStatic type.
 * 
 * @template T The type of condition returned by the builder (e.g., SQL for PostgreSQL, Filter<Document> for MongoDB)
 */
export interface ConditionBuilder<T = unknown> {
    /**
     * Build filter conditions from Rebase FilterValues
     */
    buildFilterConditions<M extends Record<string, unknown>>(
        filter: FilterValues<Extract<keyof M, string>>,
        collectionPath: string,
        ...args: unknown[]
    ): T[];

    /**
     * Build search conditions for text search
     */
    buildSearchConditions(
        searchString: string,
        properties: Record<string, unknown>,
        ...args: unknown[]
    ): T[];

    /**
     * Combine multiple conditions with AND operator
     */
    combineConditionsWithAnd(conditions: T[]): T | undefined;

    /**
     * Combine multiple conditions with OR operator
     */
    combineConditionsWithOr(conditions: T[]): T | undefined;
}

/**
 * Static condition builder type for implementations using static methods.
 * Use this type when the class provides static methods rather than instance methods.
 * 
 * @example
 * // DrizzleConditionBuilder satisfies this type
 * const builder: ConditionBuilderStatic<SQL> = DrizzleConditionBuilder;
 */
export type ConditionBuilderStatic<T = unknown> = {
    buildFilterConditions<M extends Record<string, unknown>>(
        filter: FilterValues<Extract<keyof M, string>>,
        ...args: unknown[]
    ): T[];
    buildSearchConditions(
        searchString: string,
        properties: Record<string, unknown>,
        ...args: unknown[]
    ): T[];
    combineConditionsWithAnd(conditions: T[]): T | undefined;
    combineConditionsWithOr(conditions: T[]): T | undefined;
};

// =============================================================================
// ENTITY REPOSITORY INTERFACES
// =============================================================================

/**
 * Abstract entity repository interface.
 * Handles all CRUD operations for entities in the database.
 * 
 * Implementations should handle:
 * - Entity serialization/deserialization
 * - Relation resolution
 * - ID generation and conversion
 */
export interface EntityRepository {
    /**
     * Fetch a single entity by ID
     */
    fetchEntity<M extends Record<string, unknown>>(
        collectionPath: string,
        entityId: string | number,
        databaseId?: string
    ): Promise<Entity<M> | undefined>;

    /**
     * Fetch a collection of entities with optional filtering, ordering, and pagination
     */
    fetchCollection<M extends Record<string, unknown>>(
        collectionPath: string,
        options?: FetchCollectionOptions<M>
    ): Promise<Entity<M>[]>;

    /**
     * Search entities by text
     */
    searchEntities<M extends Record<string, unknown>>(
        collectionPath: string,
        searchString: string,
        options?: SearchOptions<M>
    ): Promise<Entity<M>[]>;

    /**
     * Count entities in a collection
     */
    countEntities<M extends Record<string, unknown>>(
        collectionPath: string,
        options?: CountOptions<M>
    ): Promise<number>;

    /**
     * Save an entity (create or update)
     */
    saveEntity<M extends Record<string, unknown>>(
        collectionPath: string,
        values: Partial<M>,
        entityId?: string | number,
        databaseId?: string
    ): Promise<Entity<M>>;

    /**
     * Delete an entity by ID
     */
    deleteEntity(
        collectionPath: string,
        entityId: string | number,
        databaseId?: string
    ): Promise<void>;

    /**
     * Check if a field value is unique in a collection
     */
    checkUniqueField(
        collectionPath: string,
        fieldName: string,
        value: unknown,
        excludeEntityId?: string,
        databaseId?: string
    ): Promise<boolean>;

}

// =============================================================================
// REALTIME INTERFACES
// =============================================================================

/**
 * Configuration for subscribing to a collection
 */
export interface CollectionSubscriptionConfig {
    clientId: string;
    path: string;
    filter?: unknown;
    orderBy?: string;
    order?: "desc" | "asc";
    limit?: number;
    startAfter?: unknown;
    databaseId?: string;
    searchString?: string;
}

/**
 * Configuration for subscribing to a single entity
 */
export interface EntitySubscriptionConfig {
    clientId: string;
    path: string;
    entityId: string | number;
}

/**
 * Abstract realtime provider interface.
 * Handles real-time subscriptions and notifications for entity changes.
 */
export interface RealtimeProvider {
    /**
     * Subscribe to collection changes
     */
    subscribeToCollection(
        subscriptionId: string,
        config: CollectionSubscriptionConfig,
        callback?: (entities: Entity[]) => void
    ): void;

    /**
     * Subscribe to single entity changes
     */
    subscribeToEntity(
        subscriptionId: string,
        config: EntitySubscriptionConfig,
        callback?: (entity: Entity | null) => void
    ): void;

    /**
     * Unsubscribe from a subscription
     */
    unsubscribe(subscriptionId: string): void;

    /**
     * Notify all relevant subscribers of an entity update
     */
    notifyEntityUpdate(
        path: string,
        entityId: string,
        entity: Entity | null,
        databaseId?: string
    ): Promise<void>;
}

// =============================================================================
// COLLECTION REGISTRY INTERFACES
// =============================================================================

/**
 * Abstract collection registry interface.
 * Manages registration and lookup of entity collections.
 */
export interface CollectionRegistryInterface {
    /**
     * Register a collection
     */
    register(collection: EntityCollection): void;

    /**
     * Get a collection by its path
     */
    getCollectionByPath(path: string): EntityCollection | undefined;

    /**
     * Get all registered collections
     */
    getCollections(): EntityCollection[];
}

// =============================================================================
// DATA TRANSFORMER INTERFACES
// =============================================================================

/**
 * Abstract data transformer interface.
 * Handles serialization/deserialization between frontend and database formats.
 */
export interface DataTransformer {
    /**
     * Transform entity data for storage in the database
     */
    serializeToDatabase<M extends Record<string, unknown>>(
        entity: M,
        collection: EntityCollection
    ): Record<string, unknown>;

    /**
     * Transform database data back to entity format
     */
    deserializeFromDatabase<M extends Record<string, unknown>>(
        data: Record<string, unknown>,
        collection: EntityCollection
    ): Promise<M>;
}

// =============================================================================
// DATABASE ADMIN — CAPABILITY-SPECIFIC INTERFACES (1.3)
// =============================================================================

/**
 * Administrative operations for SQL-based databases (PostgreSQL, MySQL, etc.).
 * Used by the SQL Editor, RLS Editor, and schema browser.
 *
 * @group Admin
 */
export interface SQLAdmin {
    /**
     * Execute raw SQL against the database.
     */
    executeSql(sql: string, options?: { database?: string; role?: string }): Promise<Record<string, unknown>[]>;

    /**
     * Fetch the available databases on the server.
     */
    fetchAvailableDatabases?(): Promise<string[]>;

    /**
     * Fetch the available database roles.
     */
    fetchAvailableRoles?(): Promise<string[]>;

    /**
     * Fetch the current database name.
     */
    fetchCurrentDatabase?(): Promise<string | undefined>;
}

/**
 * Administrative operations for document-based databases (MongoDB, Firestore, etc.).
 * Used by future document administration tools.
 *
 * @group Admin
 */
export interface DocumentAdmin {
    /**
     * Execute an aggregation pipeline or equivalent query.
     */
    executeAggregate?(pipeline: Record<string, unknown>[]): Promise<Record<string, unknown>[]>;

    /**
     * Fetch statistics for a collection (document count, size, etc.).
     */
    fetchCollectionStats?(collectionName: string): Promise<{ count: number; sizeBytes?: number }>;
}

/**
 * Administrative operations for schema management.
 * Shared across SQL and document databases.
 *
 * @group Admin
 */
export interface SchemaAdmin {
    /**
     * Fetch database tables/collections not yet mapped to a Rebase collection.
     */
    fetchUnmappedTables?(mappedPaths?: string[]): Promise<string[]>;

    /**
     * Fetch column/field metadata for a single table/collection.
     * The return type is generic — SQL backends return TableMetadata,
     * document backends may return a different shape.
     */
    fetchTableMetadata?(tableName: string): Promise<unknown>;
}

/**
 * Metadata for a database branch.
 * @group Admin
 */
export interface BranchInfo {
    /** Branch name (without prefix). */
    name: string;
    /** The database this branch was created from. */
    parentDatabase: string;
    /** When the branch was created. */
    createdAt: Date;
    /** Size in bytes, if available from the server. */
    sizeBytes?: number;
}

/**
 * Administrative operations for database branching.
 * Allows creating isolated database copies for development/preview workflows.
 *
 * @group Admin
 */
export interface BranchAdmin {
    /** Create a new branch (database copy) from the current or specified source database. */
    createBranch(name: string, options?: { source?: string }): Promise<BranchInfo>;

    /** Delete a branch database. Cannot delete the main/default database. */
    deleteBranch(name: string): Promise<void>;

    /** List all branches (databases that were created via branching). */
    listBranches(): Promise<BranchInfo[]>;

    /** Get info about a specific branch. */
    getBranchInfo(name: string): Promise<BranchInfo | undefined>;
}

/**
 * Union type for all admin capabilities.
 * A backend may implement any combination of these interfaces.
 *
 * Use type guards (`isSQLAdmin`, `isDocumentAdmin`, `isSchemaAdmin`, `isBranchAdmin`)
 * to safely narrow the type before calling methods.
 *
 * @group Admin
 */
export type DatabaseAdmin = Partial<SQLAdmin> & Partial<DocumentAdmin> & Partial<SchemaAdmin> & Partial<BranchAdmin>;

/**
 * Type guard: does this admin support SQL operations?
 * @group Admin
 */
export function isSQLAdmin(admin: DatabaseAdmin | undefined): admin is SQLAdmin {
    return !!admin && typeof (admin as SQLAdmin).executeSql === "function";
}

/**
 * Type guard: does this admin support document operations?
 * @group Admin
 */
export function isDocumentAdmin(admin: DatabaseAdmin | undefined): admin is DocumentAdmin {
    return !!admin && (
        typeof (admin as DocumentAdmin).executeAggregate === "function" ||
        typeof (admin as DocumentAdmin).fetchCollectionStats === "function"
    );
}

/**
 * Type guard: does this admin support schema management?
 * @group Admin
 */
export function isSchemaAdmin(admin: DatabaseAdmin | undefined): admin is SchemaAdmin {
    return !!admin && (
        typeof (admin as SchemaAdmin).fetchUnmappedTables === "function" ||
        typeof (admin as SchemaAdmin).fetchTableMetadata === "function"
    );
}

/**
 * Type guard: does this admin support database branching?
 * @group Admin
 */
export function isBranchAdmin(admin: DatabaseAdmin | undefined): admin is BranchAdmin {
    return !!admin && typeof (admin as BranchAdmin).createBranch === "function";
}

// =============================================================================
// LIFECYCLE INTERFACES (1.4)
// =============================================================================

/**
 * Health check result returned by `healthCheck()`.
 * @group Lifecycle
 */
export interface HealthCheckResult {
    /** Whether the backend is healthy and able to serve requests. */
    healthy: boolean;
    /** Round-trip latency to the database in milliseconds. */
    latencyMs: number;
    /** Optional details (e.g., pool stats, replication lag). */
    details?: Record<string, unknown>;
}

/**
 * Lifecycle contract for backend components that hold resources
 * (database connections, WebSocket pools, timers, etc.).
 *
 * All methods are optional — simple backends (e.g., in-memory) can skip them.
 * @group Lifecycle
 */
export interface BackendLifecycle {
    /**
     * Initialize the backend: open connections, run migrations, seed data.
     * Called once during startup. Idempotent.
     */
    initialize?(): Promise<void>;

    /**
     * Check whether the backend is healthy and reachable.
     * Should be fast (< 1 s) and safe to call frequently.
     */
    healthCheck?(): Promise<HealthCheckResult>;

    /**
     * Gracefully shut down: close connections, flush buffers, cancel timers.
     * After calling `destroy()`, no other methods should be called.
     */
    destroy?(): Promise<void>;
}

// =============================================================================
// BACKEND FACTORY INTERFACES
// =============================================================================

/**
 * Configuration for creating a database backend
 */
export interface BackendConfig {
    /**
     * Type of database backend
     */
    type: string;

    /**
     * Database connection (implementation-specific)
     */
    connection: unknown;

    /**
     * Schema definition (implementation-specific, e.g., Drizzle schema for PostgreSQL)
     */
    schema?: unknown;
}

/**
 * A complete backend instance with all required services.
 *
 * Now includes optional lifecycle management and admin capabilities.
 */
export interface BackendInstance extends BackendLifecycle {
    /**
     * Entity repository for CRUD operations
     */
    entityRepository: EntityRepository;

    /**
     * Realtime provider for subscriptions
     */
    realtimeProvider: RealtimeProvider;

    /**
     * Collection registry
     */
    collectionRegistry: CollectionRegistryInterface;

    /**
     * The underlying database connection
     */
    connection: DatabaseConnection;

    /**
     * Administrative operations (SQL, schema, documents).
     * What's available depends on the backend type — use type guards
     * (`isSQLAdmin`, `isSchemaAdmin`, etc.) to narrow.
     */
    admin?: DatabaseAdmin;
}

/**
 * Factory function type for creating backend instances
 */
export type BackendFactory<TConfig extends BackendConfig = BackendConfig> =
    (config: TConfig) => BackendInstance;

// =============================================================================
// BACKEND BOOTSTRAPPER (1.2)
// =============================================================================

/**
 * A `BackendBootstrapper` encapsulates all driver-specific initialization logic.
 *
 * Instead of hard-coding Postgres setup into `initializeRebaseBackend()`,
 * each database backend provides its own bootstrapper that knows how to:
 * - Create the DataDriver from a config object
 * - Optionally initialize auth tables
 * - Optionally create a realtime service
 * - Mount driver-specific API routes
 *
 * The main `initializeRebaseBackend()` becomes a **coordinator** that iterates
 * registered bootstrappers, calls their hooks, and wires the results together.
 *
 * @group Backend
 *
 * @example
 * ```typescript
 * // Third-party MySQL bootstrapper
 * const mysqlBootstrapper: BackendBootstrapper = {
 *   type: "mysql",
 *   initializeDriver: async (config) => new MySQLDataDriver(config.connection),
 *   initializeRealtime: async (config) => new MySQLChangeStreamRealtime(config.connection),
 * };
 * 
 * initializeRebaseBackend({
 *   ...config,
 *   bootstrappers: [postgresBootstrapper, mysqlBootstrapper]
 * });
 * ```
 */
export interface BackendBootstrapper {
    /**
     * Which driver type this bootstrapper handles.
     * Must match the `type` field on the driver config object
     * (e.g., `"postgres"`, `"mongodb"`, `"mysql"`).
     */
    type: string;

    /**
     * Create a DataDriver from the given config.
     * This is the only **required** method.
     */
    initializeDriver(config: unknown): Promise<InitializedDriver>;

    /**
     * Initialize auth tables / services if this driver supports them.
     * Return undefined if auth is not supported by this backend.
     */
    initializeAuth?(config: unknown, driverResult: InitializedDriver): Promise<BootstrappedAuth | undefined>;

    /**
     * Initialize history tables / services if this driver supports them.
     * Return undefined if history is not supported by this backend.
     */
    initializeHistory?(config: unknown, driverResult: InitializedDriver): Promise<{ historyService: unknown } | undefined>;

    /**
     * Create a realtime provider for this driver.
     * Return undefined if the driver does not support realtime.
     */
    initializeRealtime?(config: unknown, driverResult: InitializedDriver): Promise<RealtimeProvider | undefined>;

    /**
     * Mount any driver-specific HTTP routes (e.g., custom admin endpoints).
     * Called after all drivers are initialized.
     */
    mountRoutes?(app: unknown, basePath: string, driverResult: InitializedDriver): void;

    /**
     * Return admin capabilities for this driver.
     */
    getAdmin?(driverResult: InitializedDriver): DatabaseAdmin | undefined;

    /**
     * Initialize WebSocket server for realtime operations.
     */
    initializeWebsockets?(server: unknown, realtimeService: RealtimeProvider, driver: import("../controllers/data_driver").DataDriver, config?: unknown): Promise<void> | void;
}

/**
 * Result of `BackendBootstrapper.initializeDriver()`.
 * @group Backend
 */
export interface InitializedDriver {
    /** The DataDriver instance, ready for use. */
    driver: import("../controllers/data_driver").DataDriver;

    /** The realtime service, if the driver created one during init. */
    realtimeProvider?: RealtimeProvider;

    /** A collection registry to register schema / tables into. */
    collectionRegistry?: CollectionRegistryInterface;

    /** The underlying database connection (for lifecycle management). */
    connection?: DatabaseConnection;

    /**
     * Opaque handle that the bootstrapper can use in subsequent hooks
     * (e.g., `initializeAuth`, `mountRoutes`) to access driver internals.
     * Not used by the coordinator.
     */
    internals?: unknown;
}

/**
 * Result of `BackendBootstrapper.initializeAuth()`.
 * @group Backend
 */
export interface BootstrappedAuth {
    /** User management service. */
    userService: unknown;
    /** Role management service. */
    roleService: unknown;
    /** Email service (optional). */
    emailService?: unknown;
    /** Combined Auth Repository for unified token and user management. */
    authRepository?: unknown;
}

import { AuthController, RebaseData } from "../controllers";
import { User } from "../users";
import { EntityCollection } from "./collections";
import { AppView } from "../controllers/navigation";

export type EntityCollectionsBuilder<EC extends EntityCollection = EntityCollection> = (params: {
    user: User | null,
    authController: AuthController,
    data: RebaseData
}) => EC[] | Promise<EC[]>;

export type AppViewsBuilder = (params: {
    user: User | null,
    authController: AuthController,
    data: RebaseData
}) => AppView[] | Promise<AppView[]>;

import React, { Dispatch, SetStateAction } from "react";
import { Entity, EntityStatus, EntityValues } from "./entities";
import { EntityCallbacks } from "./entity_callbacks";

import { EnumValues, Properties } from "./properties";
import { ExportConfig } from "./export_import";
import { EntityOverrides } from "./entity_overrides";
import { User } from "../users";
import { RebaseContext } from "../rebase_context";
import { Relation } from "./relations";
import { EntityCustomView } from "./entity_views";
import { EntityAction } from "./entity_actions";

/**
 * Base interface containing all driver-agnostic collection properties.
 * Use {@link PostgresCollection} or {@link FirebaseCollection} for
 * driver-specific type safety, or {@link EntityCollection} when you
 * need to handle any collection regardless of backend.
 *
 * @group Models
 */
export interface BaseEntityCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User> {

    /**
     * You can set an alias that will be used internally instead of the `path`.
     * The `alias` value will be used to determine the URL of the collection,
     * while `path` will still be used in the driver.
     * Note that you can use this value in reference properties too.
     */
    slug: string;

    /**
     * Name of the collection, typically plural.
     * E.g. `Products`, `Blog`
     */
    name: string;

    /**
     * Singular name of an entry in this collection
     * E.g. `Product`, `Blog entry`
     */
    singularName?: string;

    /**
     * Optional description of this view. You can use Markdown.
     */
    description?: string;

    /**
     * Child collections nested under entities of this collection.
     * Populated automatically during normalization from driver-specific fields
     * (e.g. Firebase `subcollections`, Postgres `relations` with many-cardinality).
     *
     * Custom drivers can set this directly to expose child collections to the UI.
     */
    childCollections?: () => EntityCollection<Record<string, unknown>>[];



    /**
     * Which driver handles this collection.
     * Use this to route collections to different backends:
     * - `"postgres"` - Route to PostgreSQL backend
     * - `"firestore"` - Route to Firestore (client-side)
     * - `"mongodb"` - Route to MongoDB backend
     * - Custom IDs for your own driver implementations
     *
     * If not specified, the default driver `"(default)"` is used.
     *
     * @example
     * // Simple - no driver needed for default
     * { slug: "products" }
     *
     * // Firestore collection (client-side real-time)
     * { slug: "analytics", driver: "firestore" }
     *
     * // Multiple databases within a driver
     * { slug: "orders", driver: "postgres", databaseId: "orders_db" }
     */
    driver?: string;

    /**
     * Which database within the driver.
     * - For Firestore: The Firestore database ID (e.g., for multi-database projects)
     * - For PostgreSQL: Schema or database name
     * - For MongoDB: Database name
     *
     * If not specified, the default database of the driver is used.
     */
    databaseId?: string;

    /**
     * Set of properties that compose an entity
     */
    properties: Properties;

    /**
     * Icon for the navigation sidebar or cards.
     */
    icon?: string | React.ReactNode;

    /**
     * Navigation group for this collection.
     */
    group?: string;

    /**
     * Array of entity views that this collection has.
     * Can be an array of `EntityCustomView` or a string representing the key of a global `EntityCustomView`.
     */
    entityViews?: (string | EntityCustomView<Record<string, unknown>>)[];

    /**
     * Default preview properties displayed when this collection is referenced to.
     */
    previewProperties?: string[];

    /**
     * Title property of the entity. This is the property that will be used
     * as the title in entity related views and references.
     * If not specified, the first property simple text property will be used.
     */
    titleProperty?: Extract<keyof M, string>;

    /**
     * When editing an entity, you can choose to open the entity in a side dialog
     * or in a full screen dialog. Defaults to `full_screen`.
     */
    openEntityMode?: "side_panel" | "full_screen";

    /**
     * Order in which the properties are displayed.
     * If you are specifying your collection as code, the order is the same as the
     * one you define in `properties`. Additional columns are added at the
     * end of the list, if the order is not specified.
     * You can use this prop to hide some properties from the table view.
     * Note that if you set this prop, other ways to hide fields, like
     * `hidden` in the property definition, will be ignored.
     * `propertiesOrder` has precedence over `hidden`.
     *     - For properties use the property key.
     *     - For additional fields use the field key.
     *     - If you have subcollections, you get a column for each subcollection,
     *       with the path (or alias) as the subcollection, prefixed with
     *       `subcollection:`. e.g. `subcollection:orders`.
     * You can use this prop to hide some properties from the table view.
     * Note that if you set this prop, other ways to hide fields, like
     * `hidden` in the property definition,will be ignored.
     * `propertiesOrder` has precedence over `hidden`.
     */
    propertiesOrder?: (Extract<keyof M, string> | string | `subcollection:${string}`)[];

    /**
     * If enabled, content is loaded in batches. If `false` all entities in the
     * collection are loaded. This means that when reaching the end of the
     * collection, the CMS will load more entities.
     * You can specify a number to specify the pagination size (50 by default)
     * Defaults to `true`
     */
    pagination?: boolean | number;


    selectionEnabled?: boolean;

    /**
     * This interface defines all the callbacks that can be used when an entity
     * is being created, updated or deleted.
     * Useful for adding your own logic or blocking the execution of the operation.
     */
    callbacks?: EntityCallbacks<M, USER>;

    /**
     * Pass your own selection controller if you want to control selected
     * entities externally.
     * @see useSelectionController
     */
    selectionController?: SelectionController<M>;

    /**
     * Force a filter in this view. If applied, the rest of the filters will
     * be disabled. Filters applied with this prop cannot be changed.
     * e.g. `forceFilter: { age: [">", 18] }`
     * e.g. `forceFilter: { related_user: ["==", new EntityReference("sdc43dsw2", "users")] }`
     */
    forceFilter?: FilterValues<Extract<keyof M, string>>;

    /**
     * Initial filters applied to the collection this collection is related to.
     * Defaults to none. Filters applied with this prop can be changed.
     * e.g. `filter: { age: [">", 18] }`
     * e.g. `filter: { related_user: ["==", new EntityReference("sdc43dsw2", "users")] }`
     */
    filter?: FilterValues<Extract<keyof M, string>>; // setting FilterValues<M> can break defining collections by code

    /**
     * Default sort applied to this collection.
     * When setting this prop, entities will have a default order
     * applied in the collection.
     * e.g. `sort: ["order", "asc"]`
     */
    sort?: [Extract<keyof M, string>, "asc" | "desc"];

    /**
     * You can add additional fields to the collection view by implementing
     * an additional field delegate.
     */
    additionalFields?: AdditionalFieldDelegate<M, USER>[];

    /**
     * Default size of the rendered collection
     */
    defaultSize?: CollectionSize;

    /**
     * Can the elements in this collection be edited inline in the collection
     * view. If this flag is set to false but `permissions.edit` is `true`, entities
     * can still be edited in the side panel
     */
    inlineEditing?: boolean;

    /**
     * Should this collection be hidden from the main navigation panel, if
     * it is at the root level, or in the entity side panel if it's a
     * subcollection.
     * It will still be accessible if you reach the specified path.
     * You can also use this collection as a reference target.
     */
    hideFromNavigation?: boolean;

    /**
     * If you want to open custom views or subcollections by default when opening the edit
     * view of an entity, you can specify the path to the view here.
     * The path is relative to the current collection. For example if you have a collection
     * that has a custom view as well as a subcollection that refers to another entity, you can
     * either specify the path to the custom view or the path to the subcollection.
     */
    defaultSelectedView?: string | DefaultSelectedViewBuilder;

    /**
     * Should the ID of this collection be hidden from the form view.
     */
    hideIdFromForm?: boolean;

    /**
     * Should the ID of this collection be hidden from the grid view.
     */
    hideIdFromCollection?: boolean;

    /**
     * If set to true, the form will be auto-saved when the user changes
     * the value of a field.
     * Defaults to false.
     * When a new entity is created, this property can be updated to generated a new ID
     */
    formAutoSave?: boolean;

    /**
     *
     */
    exportable?: boolean | ExportConfig<USER>;

    /**
     * User id of the owner of this collection. This is used only by plugins, or if you
     * are writing custom code
     */
    ownerId?: string;

    /**
     * Overrides for the entity view, like the data source or the storage source.
     */
    overrides?: EntityOverrides;

    /**
     * Width of the side dialog (in pixels) when opening an entity in this collection.
     */
    sideDialogWidth?: number | string;

    /**
     * If set to true, the default values of the properties will be applied
     * to the entity every time the entity is updated (not only when created).
     * Defaults to false.
     */
    alwaysApplyDefaultValues?: boolean;

    /**
     * If set to true, a tab including the JSON representation of the entity will be included.
     */
    includeJsonView?: boolean;

    /**
     * If set to true, changes to the entity will be saved in a subcollection.
     * This prop has no effect if the history plugin is not enabled
     */
    history?: boolean;

    /**
     * Should local changes be backed up in local storage, to prevent data loss on
     * accidental navigations.
     * - `manual_apply`: When the user navigates back to an entity with local changes,
     *   they will be prompted to restore the changes.
     * - `auto_apply`: When the user navigates back to an entity with local changes,
     *   the changes will be automatically applied.
     * - `false`: Local changes will not be backed up.
     * Defaults to `manual_apply`.
     */
    localChangesBackup?: "manual_apply" | "auto_apply" | false;

    /**
     * Default view mode for displaying this collection.
     * - "table": Display entities in a spreadsheet-like table (default)
     * - "cards": Display entities as a grid of cards with thumbnails
     * - "kanban": Display entities in a Kanban board grouped by a property
     * Defaults to "table".
     */
    defaultViewMode?: ViewMode;

    /**
     * Which view modes are available for this collection.
     * Possible values: "table", "cards", "kanban".
     * Defaults to all three: ["table", "cards", "kanban"].
     * Note: "kanban" will only be available if the collection has at least
     * one string property with enumValues defined, regardless of this setting.
     */
    enabledViews?: ViewMode[];

    /**
     * Configuration for Kanban board view mode.
     * When set, the Kanban view mode becomes available.
     */
    kanban?: KanbanConfig<M>;

    /**
     * Property key to use for ordering items.
     * Must reference a number property. When items are reordered,
     * this property will be updated to reflect the new order using
     * fractional indexing. Used by Kanban view for ordering within columns
     * and can be used for general ordering purposes.
     */
    orderProperty?: Extract<keyof M, string>;

    /**
     * Actions that can be performed on the entities in this collection.
     */
    entityActions?: EntityAction<M, USER>[];

    /**
     * Builder for the collection actions rendered in the toolbar
     */
    Actions?: React.ComponentType<CollectionActionsProps<M, USER>>[];

}

// ── Driver-specific collection types ──────────────────────────────────

/**
 * A collection backed by PostgreSQL (or any SQL database).
 * Adds support for SQL-style relations (JOINs) and Row Level Security.
 *
 * Use this type instead of {@link EntityCollection} when you want
 * compile-time safety that only SQL-relevant fields appear.
 *
 * @group Models
 */
export interface PostgresCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User>
    extends BaseEntityCollection<M, USER> {

    /**
     * The driver for this collection. For Postgres collections this
     * can be omitted (Postgres is the default) or set to `"postgres"`.
     */
    driver?: "postgres" | undefined;

    /**
     * The PostgreSQL table name for this collection.
     */
    table: string;

    /**
     * Set by the backend when the resolved table name doesn't match
     * an actual table in the database schema.
     */
    isTableMissing?: boolean;

    /**
     * For SQL databases, you can define the relations between collections here.
     * Relations describe JOINs, foreign keys, and junction tables.
     */
    relations?: Relation[];

    /**
     * Security rules for this collection (Supabase-style Row Level Security).
     * When defined, the schema generator will enable RLS on the table and
     * create the corresponding PostgreSQL policies.
     *
     * Supports three levels of expressiveness:
     * 1. **Convenience shortcuts** — `ownerField`, `access`, `roles`
     * 2. **Raw SQL** — `using` and `withCheck` for full PostgreSQL power
     * 3. **Combined** — mix shortcuts with `roles` for common patterns
     *
     * The authenticated user context is available in raw SQL via:
     * - `auth.uid()`   — the current user's ID
     * - `auth.roles()` — comma-separated app role IDs
     * - `auth.jwt()`   — full JWT claims as JSONB
     */
    securityRules?: SecurityRule[];
}

/**
 * A collection backed by Firebase / Firestore.
 * Adds support for subcollections (nested document collections).
 *
 * Use this type instead of {@link EntityCollection} when you want
 * compile-time safety that only Firestore-relevant fields appear.
 *
 * @group Models
 */
export interface FirebaseCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User>
    extends BaseEntityCollection<M, USER> {

    /**
     * The driver for this collection. Must be set to `"firestore"`.
     */
    driver: "firestore";

    /**
     * You can add subcollections to your entity in the same way you define the root
     * collections. The collections added here will be displayed when opening
     * the side dialog of an entity.
     */
    subcollections?: () => EntityCollection<Record<string, unknown>>[];
}

/**
 * A collection backed by any data source.
 * This is a discriminated union — use {@link PostgresCollection} or
 * {@link FirebaseCollection} for driver-specific type safety.
 *
 * @group Models
 */
export type EntityCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User> =
    | PostgresCollection<M, USER>
    | FirebaseCollection<M, USER>;

// ── Type guards ───────────────────────────────────────────────────────

/**
 * Type guard for PostgreSQL collections.
 * Returns true if the collection uses the Postgres driver (or the default driver).
 * @group Models
 */
export function isPostgresCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User>(
    collection: EntityCollection<M, USER>
): collection is PostgresCollection<M, USER> {
    return !collection.driver || collection.driver === "postgres";
}

/**
 * Type guard for Firebase / Firestore collections.
 * @group Models
 */
export function isFirebaseCollection<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User>(
    collection: EntityCollection<M, USER>
): collection is FirebaseCollection<M, USER> {
    return collection.driver === "firestore";
}


/**
 * Configuration for Kanban board view mode.
 * @group Collections
 */
export interface KanbanConfig<M extends Record<string, unknown> = Record<string, unknown>> {
    /**
     * Property key to use for Kanban board columns.
     * Must reference a string property with enumValues defined.
     * Entities will be grouped into columns based on this property's value.
     * The column order is determined by the order of enumValues in the property.
     */
    columnProperty: Extract<keyof M, string>;
}

/**
 * View mode for displaying a collection.
 * @group Collections
 */
export type ViewMode = "table" | "cards" | "kanban";

/**
 * Parameter passed to the `Actions` prop in the collection configuration.
 * The component will receive this prop when it is rendered in the collection
 * toolbar.
 *
 * @group Models
 */
export interface CollectionActionsProps<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User, EC extends EntityCollection<M> = EntityCollection<M>> {
    /**
     * Full collection path of this entity. This is the full path, like
     * `users/1234/addresses`
     */
    path: string;

    /**
     * Path of the last collection, like `addresses`
     */
    relativePath: string;

    /**
     * Array of the parent path segments like `['users']`
     */
    parentCollectionIds: string[];

    /**
     * The collection configuration
     */
    collection: EC;

    /**
     * Use this controller to get the selected entities and to update the
     * selected entities state.
     */
    selectionController: SelectionController<M>;

    /**
     * Use this controller to get the table controller and to update the
     * table controller state.
     */
    tableController: EntityTableController<M>;

    /**
     * Context of the app status
     */
    context: RebaseContext<USER>;

    /**
     * Count of the entities in this collection.
     * undefined means the count is still loading.
     */
    collectionEntitiesCount?: number;

}

/**
 * Use this controller to retrieve the selected entities or modify them in
 * an {@link EntityCollection}
 * @group Models
 */
export type SelectionController<M extends Record<string, unknown> = Record<string, unknown>> = {
    selectedEntities: Entity<M>[];
    setSelectedEntities: Dispatch<SetStateAction<Entity<M>[]>>;
    isEntitySelected: (entity: Entity<M>) => boolean;
    toggleEntitySelection: (entity: Entity<M>, newSelectedState?: boolean) => void;
}

/**
 * Filter conditions in a `Query.where()` clause are specified using the
 * strings `<`, `<=`, `==`, `>=`, `>`, `array-contains`, `in`, and `array-contains-any`.
 * @group Models
 */
export type WhereFilterOp =
    | "<"
    | "<="
    | "=="
    | "!="
    | ">="
    | ">"
    | "array-contains"
    | "in"
    | "not-in"
    | "array-contains-any";

/**
 * Used to define filters applied in collections
 *
 * e.g. `{ age: [">=", 18] }`
 *
 * @group Models
 */
export type FilterValues<Key extends string> =
    Partial<Record<Key, [WhereFilterOp, unknown]>>;

/**
 * Used to indicate valid filter combinations (e.g. created in Firestore)
 * If the user selects a specific filter/sort combination, the CMS checks if it's
 * valid, otherwise it reverts to the simpler valid case
 * @group Models
 */
export type FilterCombination<Key extends string> = Partial<Record<Key, "asc" | "desc">>;

/**
 * Sizes in which a collection can be rendered
 * @group Models
 */
export type CollectionSize = "xs" | "s" | "m" | "l" | "xl";

export type AdditionalFieldDelegateProps<M extends Record<string, unknown> = Record<string, unknown>, USER extends User = User> = {
    entity: Entity<M>,
    context: RebaseContext<USER>
};

/**
 * Use this interface for adding additional fields to entity collection views and forms.
 * @group Models
 */
export interface AdditionalFieldDelegate<M extends Record<string, unknown> = Record<string, unknown>,
    USER extends User = User> {

    /**
     * ID of this column. You can use this id in the `properties` field of the
     * collection in any order you want
     */
    key: string;

    /**
     * Header of this column
     */
    name: string;

    /**
     * Width of the generated column in pixels
     */
    width?: number;

    /**
     * Builder for the custom field
     */
    Builder?: React.ComponentType<{ entity: Entity<M>, context: RebaseContext<USER> }>;



    /**
     * If this column needs to update dynamically based on other properties,
     * you can define an array of keys as strings with the
     * `dependencies` prop.
     * e.g. ["name", "surname"]
     * This is a performance optimization, if you don't define dependencies
     * it will be updated in every render.
     */
    dependencies?: Extract<keyof M, string>[];

    /**
     * Use this prop to define the value of the column as a string or number.
     * This is the value that will be used for exporting the collection.
     * If `Builder` is defined, this prop will be ignored in the collection
     * view.
     * @param entity
     */
    value?: (props: {
        entity: Entity<M>,
        context: RebaseContext
    }) => string | number | Promise<string | number> | undefined;
}


